INSERT INTO `error_codes` (slug, category_id, brand_id, product_id, error_code, difficulty, estimated_time, estimated_cost, requires_official_sav, title_fr, title_en, title_de, title_it, title_es, symptom_fr, symptom_en, symptom_de, symptom_it, symptom_es, solution_fr, solution_en, solution_de, solution_it, solution_es, tools_fr, tools_en, tools_de, tools_it, tools_es, safety_warning_fr, safety_warning_en, safety_warning_de, safety_warning_it, safety_warning_es) VALUES
('z2m-205', 2, 3, 7, 'Z2M Error 205', 2, '10 min', '0 €', 0, 'Zigbee2MQTT — Error 205 (AREQ / ZDO response after 10000ms)', 'Zigbee2MQTT — Error 205 (AREQ / ZDO response timeout)', 'Zigbee2MQTT — Fehler 205 (AREQ / ZDO Timeout)', 'Zigbee2MQTT — Errore 205 (timeout risposta ZDO)', 'Zigbee2MQTT — Error 205 (timeout respuesta ZDO)', 'Appairage bloqué, message « Error 205 » ou timeout ZDO dans les journaux Zigbee2MQTT.', 'Pairing stalls; « Error 205 » or ZDO timeout in Zigbee2MQTT logs.', 'Kopplung hängt; « Error 205 » oder ZDO-Timeout in den Zigbee2MQTT-Logs.', 'Associazione bloccata; « Error 205 » o timeout ZDO nei log.', 'Emparejamiento bloqueado; « Error 205 » o timeout ZDO en los logs.', 'Rapprochez le capteur à moins d’1 m du coordinateur, activez le mode appairage sur l’appareil, puis relancez l’interview. Si l’erreur persiste : canal Zigbee fixe (évitez le 11 si Wi-Fi 2,4 GHz saturé), coupez un routeur Zigbee douteux, redémarrez Zigbee2MQTT. Dongle Sonoff-E : firmware Ember à jour.', 'Move the device within 1 m of the coordinator, start pairing on the device, retry the interview. If it persists: set a fixed Zigbee channel (avoid 11 on busy 2.4 GHz Wi-Fi), remove a flaky router, restart Zigbee2MQTT. On Sonoff-E: update Ember firmware.', 'Gerät < 1 m zum Coordinator, Kopplung am Gerät starten, Interview erneut. Bei Dauerfehler: festen Zigbee-Kanal wählen (Kanal 11 meiden bei vollem 2,4-GHz-WLAN), wackeligen Router entfernen, Zigbee2MQTT neu starten. Sonoff-E: Ember-Firmware aktualisieren.', 'Avvicinate il sensore al coordinatore (< 1 m), avviate l’associazione sul dispositivo, ripetete l’interview. Se persiste: canale Zigbee fisso, rimuovete un router instabile, riavviate Zigbee2MQTT. Su Sonoff-E: firmware Ember aggiornato.', 'Acercad el sensor al coordinador (< 1 m), iniciad el emparejamiento en el dispositivo y repetid la entrevista. Si continúa: canal Zigbee fijo, quitad un router inestable, reiniciad Zigbee2MQTT. En Sonoff-E: firmware Ember actualizado.', 'Navigateur web', 'Navigateur web', 'Navigateur web', 'Navigateur web', 'Navigateur web', NULL, NULL, NULL, NULL, NULL),
('z2m-no-route', 4, 4, 10, 'No network route', 3, '20–45 min', '0–25 € (prise routeur)', 0, 'Zigbee2MQTT — « No network route » / appareil injoignable', 'Zigbee2MQTT — « No network route » / device unreachable', 'Zigbee2MQTT — « No network route » / Gerät nicht erreichbar', 'Zigbee2MQTT — « No network route » / dispositivo irraggiungibile', 'Zigbee2MQTT — « No network route » / dispositivo inalcanzable', 'Entités « unavailable », commandes ignorées, LQI faible sur la carte réseau.', 'Entities « unavailable », commands ignored, low LQI on the network map.', 'Entitäten « unavailable », Befehle ohne Wirkung, niedrige LQI in der Karte.', 'Entità « unavailable », comandi ignorati, LQI basso sulla mappa.', 'Entidades « unavailable », órdenes ignoradas, LQI bajo en el mapa.', 'Ajoutez une **prise Zigbee alimentée** (routeur) entre le coordinateur et le capteur. Évitez les capteurs sur pile comme seul relais. Sur la carte Z2M, vérifiez le parent LQI. En dernier recours : réappairer l’appareil près d’un routeur stable.', 'Add a **mains-powered Zigbee router** (smart plug) between coordinator and sensor. Do not rely on battery devices as routers. Check parent LQI on the Z2M map. Last resort: re-pair next to a stable router.', 'Einen **strombetriebenen Zigbee-Router** (Steckdose) zwischen Coordinator und Sensor platzieren. Batteriegeräte sind keine Router. Parent-LQI prüfen. Notfall: neu koppeln am Router.', 'Aggiungete un **router Zigbee su presa** tra coordinatore e sensore. I sensori a batteria non fanno da router. Controllate LQI del parent. Ultima risorsa: riassociare vicino a un router.', 'Añadid un **router Zigbee enchufado** entre coordinador y sensor. Los sensores a pilas no enrutan. Revisad el LQI del padre. Último recurso: reemparejar junto a un router.', 'Carte réseau Z2M', 'Carte réseau Z2M', 'Carte réseau Z2M', 'Carte réseau Z2M', 'Carte réseau Z2M', NULL, NULL, NULL, NULL, NULL),
('z2m-interview-failed', 4, 4, 11, 'Interview failed', 3, '15 min', '0 €', 1, 'Zigbee2MQTT — « Interview failed »', 'Zigbee2MQTT — « Interview failed »', 'Zigbee2MQTT — « Interview failed »', 'Zigbee2MQTT — « Interview failed »', 'Zigbee2MQTT — « Interview failed »', 'Appareil visible mais entités manquantes ou « unsupported ».', 'Device listed but missing entities or « unsupported ».', 'Gerät sichtbar, aber Entitäten fehlen oder « unsupported ».', 'Dispositivo visibile ma entità mancanti o « unsupported ».', 'Dispositivo visible pero entidades faltantes o « unsupported ».', 'Mettez Zigbee2MQTT à jour (converters). Supprimez l’appareil, réinitialisez-le (procédure fabricant), réappairez à 50 cm du dongle. Tuya « sans passerelle » : maintenez le bouton d’appairage jusqu’au clignotement rapide.', 'Update Zigbee2MQTT (converters). Remove device, factory reset per vendor guide, re-pair within 50 cm of the dongle. Tuya no-hub: hold pairing button until fast blink.', 'Zigbee2MQTT aktualisieren. Gerät löschen, Werksreset, neu koppeln in 50 cm zum Stick. Tuya ohne Gateway: Pairing-Taste bis schnelles Blinken.', 'Aggiornate Zigbee2MQTT. Rimuovete il dispositivo, reset di fabbrica, riassociate a 50 cm dal dongle.', 'Actualizad Zigbee2MQTT. Eliminad el dispositivo, reset de fábrica, reemparejad a 50 cm del dongle.', 'Navigateur web', 'Navigateur web', 'Navigateur web', 'Navigateur web', 'Navigateur web', NULL, NULL, NULL, NULL, NULL),
('zha-probe-failed', 3, 6, 16, 'Failed to probe', 2, '10 min', '0 €', 0, 'ZHA — « Failed to probe » / appairage impossible', 'ZHA — « Failed to probe » / cannot pair', 'ZHA — « Failed to probe » / Kopplung scheitert', 'ZHA — « Failed to probe » / associazione fallita', 'ZHA — « Failed to probe » / emparejamiento fallido', 'Message dans les journaux ZHA au moment de l’appairage, appareil non créé.', 'ZHA log error during pairing; no device created.', 'ZHA-Fehler beim Koppeln; kein Gerät angelegt.', 'Errore ZHA durante l’associazione; nessun dispositivo creato.', 'Error ZHA al emparejar; no se crea el dispositivo.', 'Un seul coordinateur actif : désactivez Zigbee2MQTT si la même clé USB est utilisée. Rallongez USB courte (interférences). Réinitialisez l’appareil, rapprochez-le, réessayez. Vérifiez que le modèle est supporté (quirk/converter).', 'Only one coordinator: stop Zigbee2MQTT if sharing the same USB stick. Short USB extension. Factory reset device, move closer, retry. Check model support (quirk).', 'Nur ein Coordinator: Zigbee2MQTT stoppen bei gleichem USB-Stick. Kurzes USB-Verlängerungskabel. Werksreset, näher ran, erneut versuchen.', 'Un solo coordinatore: fermate Zigbee2MQTT se usate lo stesso dongle. Reset e riavvicinate il dispositivo.', 'Un solo coordinador: detened Zigbee2MQTT si compartís el mismo dongle. Reset y acercad el dispositivo.', 'Home Assistant', 'Home Assistant', 'Home Assistant', 'Home Assistant', 'Home Assistant', NULL, NULL, NULL, NULL, NULL),
('shelly-offline', 1, 1, 2, 'Device offline', 2, '5–15 min', '0 €', 1, 'Shelly — « Device offline » / injoignable', 'Shelly — « Device offline » / unreachable', 'Shelly — « Device offline » / nicht erreichbar', 'Shelly — « Device offline » / non raggiungibile', 'Shelly — « Device offline » / inalcanzable', 'Relais ne répond plus dans l’app Shelly ou Home Assistant, LED éteinte ou rouge.', 'Relay stops responding in Shelly app or Home Assistant; LED off or red.', 'Relais antwortet nicht mehr; LED aus oder rot.', 'Il relè non risponde; LED spento o rosso.', 'El relé no responde; LED apagado o rojo.', 'Vérifiez l’alimentation (neutre présent sur modèles qui l’exigent). Contrôlez que le Wi-Fi 2,4 GHz est actif (pas d’isolement AP). IP fixe ou réservation DHCP. Dernier recours : reset 5 s sur le bouton, reconfiguration Wi-Fi.', 'Check power (neutral required on some models). Ensure 2.4 GHz Wi-Fi is up (no AP isolation). DHCP reservation. Last resort: 5 s button reset, reconfigure Wi-Fi.', 'Stromversorgung prüfen (N-Leiter). 2,4-GHz-WLAN ohne AP-Isolation. DHCP-Reservierung. Notfall: Reset-Taste 5 s.', 'Verificate alimentazione e Wi-Fi 2,4 GHz. Reset 5 s se necessario.', 'Comprobad alimentación y Wi-Fi 2,4 GHz. Reset 5 s si hace falta.', 'Appli Shelly / navigateur', 'Appli Shelly / navigateur', 'Appli Shelly / navigateur', 'Appli Shelly / navigateur', 'Appli Shelly / navigateur', 'Micromodule Shelly/Sonoff sur secteur 230 V : coupez impérativement le disjoncteur au tableau avant toute manipulation du bornier ou du boîtier encastré. Ne travaillez jamais sous tension.', 'Shelly/Sonoff modules on 230 V mains: switch off the circuit breaker at the panel before touching terminals or opening an in-wall unit. Never work live.', 'Shelly/Sonoff an 230 V: Sicherung im Verteiler ausschalten, bevor Sie Klemmen berühren. Niemals unter Spannung arbeiten.', 'Micromoduli Shelly/Sonoff a 230 V: interrompete il magnetotermico al quadro prima di toccare i morsetti. Mai sotto tensione.', 'Micromódulos Shelly/Sonoff a 230 V: desconecte el magnetotérmico del cuadro antes de tocar bornes. Nunca bajo tensión.'),
('shelly-wifi-24', 1, 1, 1, 'Wi-Fi 2.4GHz Offline', 1, '5 min', '0 €', 0, 'Shelly — ne se connecte pas au Wi-Fi (5 GHz / mot de passe)', 'Shelly — won’t join Wi-Fi (5 GHz / password)', 'Shelly — verbindet nicht mit WLAN (5 GHz / Passwort)', 'Shelly — non si connette al Wi-Fi (5 GHz)', 'Shelly — no conecta al Wi-Fi (5 GHz)', 'Configuration AP Shelly-XXXXXX visible en boucle, échec après saisie SSID.', 'Shelly AP setup loop; fails after entering SSID.', 'Shelly-AP-Setup-Schleife; scheitert nach SSID.', 'Loop di configurazione AP Shelly.', 'Bucle de configuración AP Shelly.', 'Shelly = **2,4 GHz uniquement**. Désactivez temporairement le 5 GHz ou créez un SSID 2,4 GHz dédié. WPA2-PSK (évitez WPA3-only). SSID sans caractères spéciaux exotiques pour le premier essai.', 'Shelly needs **2.4 GHz only**. Disable 5 GHz temporarily or use a 2.4 GHz SSID. WPA2-PSK; avoid WPA3-only.', 'Nur **2,4 GHz**. WPA2-PSK, kein WPA3-only.', 'Solo **2,4 GHz**, WPA2-PSK.', 'Solo **2,4 GHz**, WPA2-PSK.', 'Box internet', 'Box internet', 'Box internet', 'Box internet', 'Box internet', NULL, NULL, NULL, NULL, NULL),
('sonoff-dongle-ezsp-ember', 2, 3, 6, 'EZSP / Ember driver mismatch', 3, '20 min', '0 €', 1, 'Sonoff Dongle-P vs Dongle-E — EZSP / Ember et mauvais pilote', 'Sonoff Dongle-P vs Dongle-E — EZSP / Ember driver mismatch', 'Sonoff Dongle-P vs Dongle-E — EZSP / Ember Treiber', 'Sonoff Dongle-P vs Dongle-E — EZSP / Ember', 'Sonoff Dongle-P vs Dongle-E — EZSP / Ember', 'Zigbee2MQTT ne démarre pas, « failed to start adapter », ou ZHA ne voit pas la clé.', 'Zigbee2MQTT won’t start adapter; ZHA doesn’t detect stick.', 'Zigbee2MQTT startet Adapter nicht; ZHA erkennt Stick nicht.', 'Zigbee2MQTT non avvia l’adattatore.', 'Zigbee2MQTT no inicia el adaptador.', '**Dongle-P** (CC2652P) : pilote **zStack** ou EZSP selon firmware. **Dongle-E** (EFR32) : pilote **ember** sous Z2M 2.x. Ne mélangez pas P et E sur la même config. Flashez le firmware recommandé par la doc Sonoff/Z2M avant production.', '**Dongle-P**: zStack/EZSP per firmware. **Dongle-E**: **ember** driver on Z2M 2.x. Flash vendor-recommended firmware before going live.', '**Dongle-P**: zStack; **Dongle-E**: **ember**. Firmware laut Dokumentation flashen.', '**Dongle-P**: zStack; **Dongle-E**: **ember**.', '**Dongle-P**: zStack; **Dongle-E**: **ember**.', 'PC + câble USB', 'PC + câble USB', 'PC + câble USB', 'PC + câble USB', 'PC + câble USB', 'Flash firmware sur dongle Sonoff : suivez strictement la procédure officielle ; une coupure ou un mauvais fichier peut rendre la clé inutilisable (brick) et annuler la garantie.', 'Flashing Sonoff dongle firmware: follow the official procedure only; a bad flash can brick the stick and void warranty.', 'Firmware-Flash am Sonoff-Stick: nur offizielle Anleitung; Fehl-Flash kann den Stick bricken und die Garantie erlöschen lassen.', 'Flash firmware sul dongle Sonoff: solo procedura ufficiale; un errore può brickare la chiavetta e invalidare la garanzia.', 'Flashear firmware del dongle Sonoff: solo procedimiento oficial; un fallo puede dejarlo inutilizable y anular la garantía.'),
('homey-zigbee-full', 3, 5, 13, 'Zigbee network full', 2, '10 min', '0 €', 1, 'Homey Pro / Mini — « Zigbee network full »', 'Homey Pro / Mini — « Zigbee network full »', 'Homey Pro / Mini — « Zigbee network full »', 'Homey Pro / Mini — rete Zigbee piena', 'Homey Pro / Mini — red Zigbee llena', 'Impossible d’ajouter un nouveau capteur Zigbee.', 'Cannot add new Zigbee devices.', 'Kein neues Zigbee-Gerät hinzufügbar.', 'Impossibile aggiungere nuovi dispositivi Zigbee.', 'No se pueden añadir nuevos Zigbee.', 'Supprimez les appareils fantômes, ajoutez des **routeurs** (prises Zigbee alimentées). Évitez les doublons d’intégration (même capteur sur Homey + autre coordinateur). Redémarrez Homey après nettoyage.', 'Remove ghost devices; add **mains-powered routers**. Avoid duplicate coordinators. Restart Homey after cleanup.', 'Geistergeräte löschen; strombetriebene Router hinzufügen. Homey neu starten.', 'Rimuovete dispositivi fantasma; aggiungete router su presa.', 'Eliminad dispositivos fantasma; añadid routers enchufados.', 'App Homey', 'App Homey', 'App Homey', 'App Homey', 'App Homey', NULL, NULL, NULL, NULL, NULL),
('homey-matter-failed', 3, 5, 14, 'Matter Pairing Failed', 3, '15 min', '0 €', 0, 'Homey — « Matter pairing failed »', 'Homey — « Matter pairing failed »', 'Homey — « Matter pairing failed »', 'Homey — associazione Matter fallita', 'Homey — emparejamiento Matter fallido', 'QR Matter scanné mais échec à la fin de l’commissioning.', 'Matter QR scanned but commissioning fails at the end.', 'Matter-QR gescannt, Commissioning scheitert.', 'QR Matter scansionato ma commissioning fallisce.', 'QR Matter escaneado pero falla el commissioning.', 'Réinitialisez l’appareil Matter (pas déjà lié à Apple/Google). Homey à jour, Thread border router activé si requis. Désactivez VPN sur le téléphone. Rapprochez l’appareil du Homey pour le premier appairage.', 'Factory reset Matter device (not bound elsewhere). Update Homey; enable Thread if needed. Disable phone VPN; pair close to Homey.', 'Matter-Gerät zurücksetzen. Homey aktualisieren. VPN am Handy aus.', 'Reset del dispositivo Matter. Homey aggiornato.', 'Reset del dispositivo Matter. Homey actualizado.', 'App Homey', 'App Homey', 'App Homey', 'App Homey', 'App Homey', NULL, NULL, NULL, NULL, NULL),
